  ('st-ex-tamecause-1', 'sent-ex-tamecause-1', 'en', 'Because of the rain, the match was called off.', 'authored'),
  ('st-ex-tamecause-2', 'sent-ex-tamecause-2', 'en', 'Owing to an accident, the trains are running late.', 'authored'),
  ('st-ex-tamecause-3', 'sent-ex-tamecause-3', 'en', 'I was off work because of illness.', 'authored'),
  ('st-ex-tamecause-4', 'sent-ex-tamecause-4', 'en', 'You cannot get through because of the roadworks.', 'authored'),
  ('st-ex-younimieru-1', 'sent-ex-younimieru-1', 'en', 'He looks tired.', 'authored'),
  ('st-ex-younimieru-2', 'sent-ex-younimieru-2', 'en', 'He looks well, but he is ill.', 'authored'),
  ('st-ex-younimieru-3', 'sent-ex-younimieru-3', 'en', 'That person looks like a student.', 'authored'),
  ('st-ex-younimieru-4', 'sent-ex-younimieru-4', 'en', 'The sky looks as though it has brightened.', 'authored'),
  ('st-ex-toshite-1', 'sent-ex-toshite-1', 'en', 'He works as a teacher.', 'authored'),
  ('st-ex-toshite-2', 'sent-ex-toshite-2', 'en', 'I am going to Japan as an exchange student.', 'authored'),
  ('st-ex-toshite-3', 'sent-ex-toshite-3', 'en', 'I take photographs as a hobby.', 'authored'),
  ('st-ex-toshite-4', 'sent-ex-toshite-4', 'en', 'I gave the presentation as our representative.', 'authored'),
  ('st-ex-karanikakete-1', 'sent-ex-karanikakete-1', 'en', 'From spring through to summer there is a lot of rain.', 'authored'),
  ('st-ex-karanikakete-2', 'sent-ex-karanikakete-2', 'en', 'It snowed from night through to morning.', 'authored'),
  ('st-ex-karanikakete-3', 'sent-ex-karanikakete-3', 'en', 'I am busy from this week through to next.', 'authored'),
  ('st-ex-karanikakete-4', 'sent-ex-karanikakete-4', 'en', 'A strong wind blew from the north down to the south.', 'authored'),
  ('st-ex-kawarini-1', 'sent-ex-kawarini-1', 'en', 'I am going in place of my older brother.', 'authored'),
  ('st-ex-kawarini-2', 'sent-ex-kawarini-2', 'en', 'I used vegetables instead of meat.', 'authored'),
  ('st-ex-kawarini-3', 'sent-ex-kawarini-3', 'en', 'In return for working, I get paid.', 'authored'),
  ('st-ex-kawarini-4', 'sent-ex-kawarini-4', 'en', 'I am going by bus instead of by train.', 'authored')
