SELECT g.id, s.id, 'example', s.n
FROM (VALUES
  ('tame-cause', 'sent-ex-tamecause-1', 0),
  ('tame-cause', 'sent-ex-tamecause-2', 1),
  ('tame-cause', 'sent-ex-tamecause-3', 2),
  ('tame-cause', 'sent-ex-tamecause-4', 3),
  ('you-ni-mieru', 'sent-ex-younimieru-1', 0),
  ('you-ni-mieru', 'sent-ex-younimieru-2', 1),
  ('you-ni-mieru', 'sent-ex-younimieru-3', 2),
  ('you-ni-mieru', 'sent-ex-younimieru-4', 3),
  ('toshite', 'sent-ex-toshite-1', 0),
  ('toshite', 'sent-ex-toshite-2', 1),
  ('toshite', 'sent-ex-toshite-3', 2),
  ('toshite', 'sent-ex-toshite-4', 3),
  ('kara-nikakete', 'sent-ex-karanikakete-1', 0),
  ('kara-nikakete', 'sent-ex-karanikakete-2', 1),
  ('kara-nikakete', 'sent-ex-karanikakete-3', 2),
  ('kara-nikakete', 'sent-ex-karanikakete-4', 3),
  ('kawari-ni', 'sent-ex-kawarini-1', 0),
  ('kawari-ni', 'sent-ex-kawarini-2', 1),
  ('kawari-ni', 'sent-ex-kawarini-3', 2),
  ('kawari-ni', 'sent-ex-kawarini-4', 3)
) AS s(slug, id, n)
JOIN grammar_points g ON g.language_id = 'lang-ja' AND g.slug = s.slug
ON CONFLICT (grammar_point_id, sentence_id, role) DO NOTHING;

